package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonIgnore;
import com.fasterxml.jackson.core.*;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.io.Serializable;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Reference_getDescription_TriageGen2Test {

    /**
     * Since the Reference constructor is protected, we use a subclass 
     * or reflection if necessary, but here we can use the public constructors.
     */

    @Test
    public void testGetDescription_NullDesc_NullFrom() throws Exception {
        // Using reflection to simulate the state where _from is null 
        // but we need to trigger the logic.
        // The constructor Reference(Object from) with null simulates _from == null.
        JsonMappingException.Reference ref = new JsonMappingException.Reference(null);

        // Since _from is null, the code path goes to "UNKNOWN"
        // We need to ensure _desc is null initially (which it is by default)
        assertEquals("UNKNOWN[]", ref.getDescription());
    }

    @Test
    public void testGetDescription_WithClassFrom_WithFieldName() {
        // Tests: _from is Class, _fieldName is not null
        JsonMappingException.Reference ref = new JsonMappingException.Reference(String.class, "myField");

        // Expected: packageName + '.' + simpleName + '["myField"]'
        // String is in java.lang
        String expected = "java.lang.String[\"myField\"]";
        assertEquals(expected, ref.getDescription());
    }

    @Test
    public void testGetDescription_WithObjectFrom_WithIndex() {
        // Tests: _from is instance of Object, _index >= 0
        Object obj = new Object();
        JsonMappingException.Reference ref = new JsonMappingException.Reference(obj, 5);

        // Expected: packageName + '.' + simpleName + '[5]'
        String expected = "java.lang.Object[5]";
        assertEquals(expected, ref.getDescription());
    }

    @Test
    public void testGetDescription_WithObjectFrom_WithNoFieldNoIndex() {
        // Tests: _from is instance of Object, _fieldName is null, _index < 0
        Object obj = new Object();
        JsonMappingException.Reference ref = new JsonMappingException.Reference(obj);

        // Force index to be -1 via reflection if necessary, 
        // but the constructor Reference(Object from) sets index to -1 by default.
        String expected = "java.lang.Object[?]";
        assertEquals(expected, ref.getDescription());
    }

    @Test
    public void testGetDescription_Memoization() {
        // Tests: verify that _desc is cached (memoization)
        JsonMappingException.Reference ref = new JsonMappingException.Reference(String.class, "field");
        String firstCall = ref.getDescription();
        String secondCall = ref.getDescription();

        assertEquals(firstCall, secondCall);
    }

    @Test
    public void testGetDescription_FromIsAlreadyClass() {
        // Tests the branch: (_from instanceof Class<?>) ? (Class<?>)_from : _from.getClass();
        // Passing the class directly instead of an instance
        JsonMappingException.Reference ref = new JsonMappingException.Reference(Integer.class);

        String expected = "java.lang.Integer[?]";
        assertEquals(expected, ref.getDescription());
    }

    @Test
    public void testGetDescription_ArrayClass() {
        // Tests the "butt-ugly" comment logic for arrays
        JsonMappingException.Reference ref = new JsonMappingException.Reference(String[].class);

        // ClassUtil.getPackageName for String[].class might return null or the package
        // If pkgName is null, it just appends simpleName
        String desc = ref.getDescription();
        // For String[].class, simpleName is "[Ljava.lang.String;"
        // Most likely results in "java.lang.[Ljava.lang.String;" or "[Ljava.lang.String;" depending on ClassUtil
        // We just assert it doesn't crash and contains the name.
        assert(desc.contains("String"));
    }
}
